local UI_SOUNDS = { ui_attach = 3, ui_remove = 3, ui_select = 3, ui_navigate = 1, ui_hover = 1, ui_click = 1 }

function SandSwep.UISound(name)
    local variants = UI_SOUNDS[name]
    if not variants or not CLIENT then return end

    surface.PlaySound(("sandstorm/shared/ui/%s_%02d.ogg"):format(name, math.random(variants)))
end

